import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestSomarTudo(unittest.TestCase):
    def test_somar_tudo_soma_os_itens(self):
        """somar_tudo devolve a soma dos itens da lista"""
        self.assertEqual(rodar()["somar_tudo"]([10, 20, 30]), 60)

    def test_somar_tudo_com_lista_vazia(self):
        """somar_tudo com lista vazia devolve zero"""
        self.assertEqual(rodar()["somar_tudo"]([]), 0)

    def test_somar_tudo_com_um_item(self):
        """somar_tudo com um item devolve o proprio item"""
        self.assertEqual(rodar()["somar_tudo"]([7]), 7)
